css:
.exec-comms-container {
    padding: 24px;
    background: #f5f6f8;
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
    color: #1a2744;
}
.exec-comms-container * {
    box-sizing: border-box;
}
.exec-comms-header {
    background: #1a2744;
    color: #ffffff;
    padding: 32px 36px;
    border-radius: 4px;
    margin-bottom: 22px;
    border-left: 4px solid #c9a961;
    box-shadow: 0 4px 14px rgba(26,39,68,0.12);
}
.exec-comms-eyebrow {
    color: #c9a961;
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.18em;
    margin-bottom: 10px;
    font-weight: 600;
}
.exec-comms-header h1 {
    font-size: 1.7rem;
    font-weight: 600;
    margin: 0 0 6px 0;
    letter-spacing: -0.01em;
    color: #ffffff;
}
.exec-comms-protagonist {
    color: #a8b4c8;
    font-size: 0.85rem;
    letter-spacing: 0.04em;
}
.exec-comms-period-bar {
    background: #ffffff;
    padding: 14px 24px;
    border: 1px solid #e3e6eb;
    border-radius: 4px;
    margin-bottom: 22px;
    font-size: 0.95rem;
    color: #4a5568;
    display: flex;
    align-items: center;
    gap: 8px;
}
.exec-comms-period-label {
    text-transform: uppercase;
    font-size: 0.75rem;
    letter-spacing: 0.1em;
    color: #6b7280;
    font-weight: 600;
}
.exec-comms-period-num {
    color: #1a2744;
    font-weight: 700;
}
.exec-comms-period-name {
    margin-left: 18px;
    color: #1a2744;
    font-weight: 600;
    font-size: 0.95rem;
    border-left: 2px solid #c9a961;
    padding-left: 18px;
}
.exec-comms-kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
    gap: 16px;
    margin-bottom: 24px;
}
.exec-comms-kpi-card {
    background: #ffffff;
    border: 1px solid #e3e6eb;
    border-top: 3px solid #1a2744;
    border-radius: 4px;
    padding: 22px 24px;
    transition: border-top-color 0.2s ease;
}
.exec-comms-kpi-card:hover {
    border-top-color: #c9a961;
}
.exec-comms-kpi-card-accent {
    border-top-color: #c9a961;
}
.exec-comms-kpi-label {
    color: #6b7280;
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    margin-bottom: 10px;
    font-weight: 600;
}
.exec-comms-kpi-value {
    color: #1a2744;
    font-size: 2rem;
    font-weight: 700;
    letter-spacing: -0.02em;
    line-height: 1.1;
}
.exec-comms-kpi-text {
    font-size: 1.1rem;
    line-height: 1.3;
}
.exec-comms-briefing {
    background: #ffffff;
    border: 1px solid #e3e6eb;
    border-left: 4px solid #c9a961;
    border-radius: 4px;
    padding: 28px 32px;
    margin-bottom: 22px;
}
.exec-comms-briefing-eyebrow {
    color: #c9a961;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.16em;
    margin-bottom: 8px;
    font-weight: 600;
}
.exec-comms-briefing-title {
    color: #1a2744;
    font-size: 1.45rem;
    font-weight: 600;
    margin: 0 0 4px 0;
    letter-spacing: -0.01em;
}
.exec-comms-briefing-register {
    color: #6b7280;
    font-size: 0.85rem;
    font-style: italic;
    margin-bottom: 18px;
    border-bottom: 1px solid #e3e6eb;
    padding-bottom: 14px;
}
.exec-comms-briefing-body {
    color: #2d3748;
    font-size: 0.96rem;
    line-height: 1.7;
}
.exec-comms-briefing-body strong {
    color: #1a2744;
    font-weight: 600;
}
.exec-comms-briefing-body em {
    color: #4a5568;
    font-style: italic;
}
.exec-comms-decisions {
    background: #ffffff;
    border: 1px solid #e3e6eb;
    border-radius: 4px;
    padding: 28px 32px;
    margin-bottom: 22px;
}
.exec-comms-decisions h3 {
    color: #1a2744;
    font-size: 1rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    margin: 0 0 22px 0;
    padding-bottom: 12px;
    border-bottom: 2px solid #1a2744;
}
.exec-comms-decision-list {
    display: flex;
    flex-direction: column;
    gap: 24px;
}
.exec-comms-decision-item {
    padding-bottom: 20px;
    border-bottom: 1px dashed #e3e6eb;
}
.exec-comms-decision-item:last-child {
    border-bottom: none;
    padding-bottom: 0;
}
.exec-comms-decision-label {
    color: #1a2744;
    font-size: 0.98rem;
    font-weight: 600;
    margin-bottom: 4px;
    display: block;
}
.exec-comms-decision-hint {
    color: #6b7280;
    font-size: 0.83rem;
    font-style: italic;
    margin-bottom: 10px;
    line-height: 1.5;
}
.exec-comms-decisions select {
    background: #ffffff;
    color: #1a2744;
    border: 1px solid #cbd5e0;
    border-radius: 4px;
    padding: 11px 14px;
    width: 100%;
    font-size: 0.9rem;
    font-family: inherit;
}
.exec-comms-decisions select:focus {
    outline: none;
    border-color: #1a2744;
    box-shadow: 0 0 0 2px rgba(26,39,68,0.12);
}
.exec-comms-decisions select option {
    background: #ffffff;
    color: #1a2744;
    padding: 8px;
}
.exec-comms-decisions input[type="number"],
.exec-comms-decisions input[type="text"] {
    background: #ffffff;
    color: #1a2744;
    border: 1px solid #cbd5e0;
    border-radius: 4px;
    padding: 10px 14px;
    width: 100%;
    font-size: 0.9rem;
    font-family: inherit;
}
.exec-comms-actions {
    margin-top: 28px;
    padding-top: 20px;
    border-top: 1px solid #e3e6eb;
    display: flex;
    gap: 14px;
    align-items: center;
    flex-wrap: wrap;
}
.exec-comms-submit {
    background: #1a2744;
    border: 1px solid #1a2744;
    color: #ffffff;
    padding: 11px 30px;
    font-size: 0.85rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    border-radius: 4px;
    transition: background 0.2s ease, border-color 0.2s ease;
    cursor: pointer;
}
.exec-comms-submit:hover {
    background: #2d3f63;
    border-color: #2d3f63;
    color: #ffffff;
}
.exec-comms-submit:focus {
    outline: none;
    box-shadow: 0 0 0 3px rgba(201,169,97,0.35);
}
.exec-comms-undo {
    background: #ffffff;
    border: 1px solid #cbd5e0;
    color: #4a5568;
    padding: 9px 20px;
    border-radius: 4px;
    font-size: 0.8rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    font-weight: 600;
}
.exec-comms-undo:hover {
    background: #f5f6f8;
    color: #1a2744;
    border-color: #1a2744;
}
.exec-comms-completion-message {
    background: #f5f6f8;
    border-left: 4px solid #c9a961;
    padding: 24px 28px;
    color: #1a2744;
    font-size: 1rem;
    line-height: 1.6;
    border-radius: 4px;
}
.exec-comms-completion-message strong {
    color: #1a2744;
}
.exec-comms-history {
    background: #ffffff;
    border: 1px solid #e3e6eb;
    border-radius: 4px;
    padding: 24px 28px;
    margin-bottom: 22px;
}
.exec-comms-history h3 {
    color: #1a2744;
    font-size: 1rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    margin: 0 0 16px 0;
}
.exec-comms-history table {
    width: 100%;
    font-size: 0.88rem;
    color: #2d3748;
    margin-bottom: 0;
}
.exec-comms-history table th {
    background: #f5f6f8;
    color: #1a2744;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.08em;
    padding: 12px;
    border-bottom: 2px solid #1a2744;
    text-align: left;
    font-weight: 600;
}
.exec-comms-history table td {
    padding: 12px;
    border-bottom: 1px solid #e3e6eb;
    color: #2d3748;
}
.exec-comms-history table tr:last-child td {
    border-bottom: none;
}
.exec-comms-chart-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 20px;
    margin-bottom: 24px;
}
.exec-comms-chart-panel {
    background: #ffffff;
    border: 1px solid #e3e6eb;
    border-top: 3px solid #1a2744;
    border-radius: 4px;
    padding: 22px 26px;
    height: 340px;
    display: flex;
    flex-direction: column;
}
.exec-comms-chart-panel h3 {
    color: #1a2744;
    font-size: 0.92rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    margin: 0 0 14px 0;
}
.exec-comms-chart-panel canvas {
    flex: 1;
    max-height: 270px;
}
@media (max-width: 768px) {
    .exec-comms-container {
        padding: 16px;
    }
    .exec-comms-header {
        padding: 24px 22px;
    }
    .exec-comms-header h1 {
        font-size: 1.35rem;
    }
    .exec-comms-briefing,
    .exec-comms-decisions,
    .exec-comms-history {
        padding: 20px;
    }
    .exec-comms-chart-grid {
        grid-template-columns: 1fr;
    }
    .exec-comms-kpi-value {
        font-size: 1.55rem;
    }
    .exec-comms-period-bar {
        flex-wrap: wrap;
    }
    .exec-comms-period-name {
        margin-left: 0;
        padding-left: 0;
        border-left: none;
        border-top: 1px solid #e3e6eb;
        padding-top: 8px;
        margin-top: 6px;
        width: 100%;
    }
}
.exec-comms-container :focus-visible,
.exec-comms-container button:focus-visible,
.exec-comms-container select:focus-visible,
.exec-comms-container input:focus-visible,
.exec-comms-select:focus-visible {
    outline: 3px solid #1a2744;
    outline-offset: 2px;
}
.exec-comms-debrief {
    background: #ffffff; border: 1px solid #d6d9df; border-left: 5px solid #1a2744;
    border-radius: 4px; padding: 20px 24px; color: #1f2937; margin-bottom: 20px;
}
.exec-comms-debrief h3 { margin: 0 0 12px 0; font-size: 1.15rem; }
.exec-comms-debrief h4 { margin: 18px 0 8px 0; font-size: 0.95rem; }
.exec-comms-debrief-table { width: 100%; border-collapse: collapse; }
.exec-comms-debrief-table th, .exec-comms-debrief-table td {
    text-align: left; padding: 6px 8px; border-bottom: 1px solid #e6e8ec; font-size: 0.9rem; color: #1f2937;
}
.exec-comms-debrief-table th { font-weight: 600; width: 55%; }
@media (prefers-reduced-motion: reduce) {
    .exec-comms-container *, .exec-comms-container *::before, .exec-comms-container *::after {
        animation-duration: 0.001ms !important; animation-iteration-count: 1 !important;
        transition-duration: 0.001ms !important; scroll-behavior: auto !important;
    }
}

