        _composite(ds, state) {
            var hist = (state && state.history) || [];
            var total = 0;
            var maxPer = 100;
            for (var i = 0; i < hist.length; i++) {
                var r = hist[i] && hist[i].results;
                if (r && typeof r.roundScore === 'number') total += r.roundScore;
            }
            if (typeof ds.totalScore === 'number' && ds.totalScore > total) total = ds.totalScore;
            var rounds = Math.max(1, (this.ROUNDS || []).length);
            var score = Math.max(0, Math.min(100, (total / (rounds * maxPer)) * 100));
            var integrity = (ds.integrity !== undefined) ? ds.integrity : null;
            var caps = [];
            if (integrity !== null && integrity < 40) { caps.push('voiceBroke'); score = Math.min(score, 60); }
            var key = 'developing';
            if (score >= 50) key = 'serviceable';
            if (score >= 68) key = 'composed';
            if (score >= 84) key = 'kesterson';
            var grade = 'F';
            if (score >= 85) grade = 'A';
            else if (score >= 70) grade = 'B';
            else if (score >= 55) grade = 'C';
            else if (score >= 40) grade = 'D';
            return {
                overallScore: parseFloat(score.toFixed(1)),
                totalScore: parseFloat(score.toFixed(1)),
                composite: parseFloat(score.toFixed(1)),
                score: parseFloat(score.toFixed(1)),
                rawTotal: total,
                grade: grade,
                performanceKey: key,
                failureStates: caps
            };
        }

        formatCompletionMessage(summary) {
            var t = function(k) { return window.mySimulation.t(k); };
            var s = summary || {};
            var rows = [
                [t('sum_score'), (s.overallScore !== undefined ? s.overallScore : 0) + ' / 100 (' + (s.grade || '-') + ')'],
                [t('sum_band'), s.performanceLabel || '']
