            var html = '<div class="exec-comms-debrief" role="status" aria-live="polite">';
            html += '<h3>' + t('debrief_title') + '</h3><table class="exec-comms-debrief-table"><tbody>';
            rows.forEach(function(r) { html += '<tr><th scope="row">' + r[0] + '</th><td>' + r[1] + '</td></tr>'; });
            html += '</tbody></table>';
            var ins = s.insights || [];
            if (ins.length) {
                html += '<h4>' + t('debrief_insights') + '</h4><ul>';
