        getPerformanceSummary(history) {
            if (!history || !history.length) return {};
            var total = 0;
            var firstPersonTotal = 0;
            for (var i = 0; i < history.length; i++) {
                var r = history[i].results || {};
                total += (r.roundScore || 0);
                firstPersonTotal += (r.firstPersonCount || 0);
            }
            var max = history.length * 100;
            var pct = max > 0 ? (total / max) : 0;
            var integrity = (history[history.length - 1].results && history[history.length - 1].results.integrity) || 0;

            var tr = this._tr.bind(this);
            var performance = 'First Draft';
            if (pct >= 0.85 && integrity >= 80) performance = tr('perf_master');
            else if (pct >= 0.70) performance = tr('perf_composed');
            else if (pct >= 0.55) performance = tr('perf_working');
            else performance = tr('perf_first');

            var insights = [];
            if (integrity >= 90) insights.push(tr('ins_integrity_held'));
            if (integrity < 60) insights.push(tr('ins_integrity_eroded'));
            if (firstPersonTotal >= 10) insights.push(tr('ins_first_person'));
            if (firstPersonTotal <= 4) insights.push(tr('ins_plural'));
            if (pct >= 0.85) insights.push(tr('ins_pass'));
            if (pct < 0.55) insights.push(tr('ins_reread'));
            var __ds = (window.mySimulation && window.mySimulation.state && window.mySimulation.state.domainState) || {};
            var __perf = (__ds.performance && __ds.performance.overallScore !== undefined)
                ? __ds.performance
                : this._composite(__ds, window.mySimulation ? window.mySimulation.state : null);
            var __t = function(k) { return window.mySimulation.t(k); };


            return {
                overallScore: __perf.overallScore,
                totalScore: __perf.overallScore,
                composite: __perf.overallScore,
                score: __perf.overallScore,
                grade: __perf.grade,
                performanceKey: __perf.performanceKey,
                performanceLabel: __t('band_' + __perf.performanceKey),
                failureStates: __perf.failureStates || [],
                totalScore: total,
                maxScore: max,
                scorePercent: Math.round(pct * 100),
                compositionIntegrity: Math.round(integrity),
                firstPersonTotal: firstPersonTotal,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
