        _updateBriefing(state, keepChoices) {
            this.__keepChoices = keepChoices || null;
            var period = (state && state.currentPeriod) || 1;
            var subtitleEl = document.getElementById('briefingSubtitle');
            var titleEl = document.getElementById('briefingTitle');
            var registerEl = document.getElementById('briefingRegister');
            var bodyEl = document.getElementById('briefingBody');
            var listEl = document.getElementById('decisionList');
            var periodNameEl = document.getElementById('periodName');
            var kpiRoundEl = document.getElementById('kpiRoundDisplay');

            // the ROUNDS text fields hold translation keys, resolved here at render time
            var tr = this._tr.bind(this);

            if (period > this.ROUNDS.length) {
                if (subtitleEl) subtitleEl.textContent = tr('done_subtitle');
                if (titleEl) titleEl.textContent = tr('done_title');
                if (registerEl) registerEl.textContent = tr('done_register');
                if (bodyEl) bodyEl.innerHTML = tr('done_body');
                if (listEl) listEl.innerHTML = '<div class="exec-comms-completion-message">' + tr('done_list') + '</div>';
                if (periodNameEl) periodNameEl.textContent = '· ' + tr('done_subtitle');
                if (kpiRoundEl) kpiRoundEl.textContent = tr('done_kpi');
                return;
            }

            var idx = Math.min(period - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            if (subtitleEl) subtitleEl.textContent = tr(round.subtitle);
            if (titleEl) titleEl.textContent = tr(round.title);
            if (registerEl) registerEl.textContent = tr(round.register);
            if (bodyEl) bodyEl.innerHTML = tr(round.briefing);
            if (periodNameEl) periodNameEl.textContent = '· ' + tr(round.shortTitle);
            if (kpiRoundEl) kpiRoundEl.textContent = tr(round.shortTitle);

            if (listEl) {
                listEl.innerHTML = '';
                for (var i = 0; i < round.decisions.length; i++) {
                    var dec = round.decisions[i];
                    var item = document.createElement('div');
                    item.className = 'exec-comms-decision-item';

                    var lbl = document.createElement('label');
                    lbl.className = 'exec-comms-decision-label';
                    lbl.setAttribute('for', dec.id);
                    lbl.textContent = (i + 1) + '. ' + tr(dec.label);
                    item.appendChild(lbl);

                    if (dec.hint) {
                        var hintEl = document.createElement('div');
                        hintEl.className = 'exec-comms-decision-hint';
                        hintEl.textContent = tr(dec.hint);
                        item.appendChild(hintEl);
                    }

                    var prevEl = document.getElementById(dec.id);
                    var prevVal = (this.__keepChoices && this.__keepChoices[dec.id]) ||
                                  (prevEl ? prevEl.value : '');
                    var sel = document.createElement('select');
                    sel.id = dec.id;
                    sel.className = 'exec-comms-select';
                    sel.__restoreValue = prevVal;

                    var placeholder = document.createElement('option');
                    placeholder.value = '';
                    placeholder.textContent = tr('choose_approach');
                    placeholder.disabled = true;
                    placeholder.selected = true;
                    sel.appendChild(placeholder);

                    for (var k = 0; k < dec.options.length; k++) {
                        var optDef = dec.options[k];
                        var optEl = document.createElement('option');
                        optEl.value = optDef.value;
                        optEl.textContent = tr(optDef.label);
                        sel.appendChild(optEl);
                    }

                    if (sel.__restoreValue) { sel.value = sel.__restoreValue; }

                    item.appendChild(sel);
                    listEl.appendChild(item);
                }
            }
        }

